#include <queue>
using namespace std;

#define rep(i,n) for(int i=0;i<n;i++)

typedef pair<pair<int,int>,int> QUEUE_NODE;

#define Q_X first.second

#define Q_Y first.first

#define Q_depth second



/*方向*/

int odd_x[] = {-1, 1, 0, 0, 1,1};

int odd_y[] = { 0, 0,-1, 1,-1, 1};



int even_x[] = {-1, 1, 0, 0,-1,-1};

int even_y[] = { 0, 0,-1, 1,-1, 1};



int main(){

	int point[100][100];

	int height,width,a_position,b_position,times,x,y,squares;

	while(cin >> width  && width){

		int answer = 0;

		cin >> height;

		rep(i,100)rep(j,100)point[i][j] = 0;

		cin >> times;

		rep(i,times){

			cin >> a_position >> b_position;

			a_position--;b_position--;

			point[b_position][a_position] = i+1;

		}

		cin >> squares;

		rep(P,squares){

			cin >> a_position >> b_position;

			a_position--;b_position--;

			point[b_position][a_position] = 50;



			int pt[100] = {0};

			rep(i,height)rep(j,width){

				x = j,y = i;

				queue<QUEUE_NODE> QUEUE;

				pair<int,int> dp[100];

				bool done[100][100]={0};

				QUEUE.push( make_pair(make_pair(y,x),0	) );

				while( QUEUE.size() ){

					QUEUE_NODE q = QUEUE.front(); QUEUE.pop();

					if(point[q.Q_Y][q.Q_X]){

						dp[q.Q_depth].first++;

						dp[q.Q_depth].second = point[q.Q_Y][q.Q_X];

				  }

					if( q.Q_Y % 2 == 1){

						rep(L,6){

							if( q.Q_X+odd_x[L] >=0 && q.Q_X+odd_x[L] < width && q.Q_Y+odd_y[L] < height && q.Q_Y+odd_y[L]>=0 ){

									if( !done[q.Q_Y+odd_y[L]][q.Q_X+odd_x[L]] )QUEUE.push( make_pair(make_pair(q.Q_Y+odd_y[L],q.Q_X+odd_x[L]),q.Q_depth+1) );

								  	done[q.Q_Y+odd_y[L]][q.Q_X+odd_x[L]] = true;

							}

						}

					}else{

						rep(L,6){

							if( q.Q_X+even_x[L] >=0 && q.Q_X+even_x[L] < width && q.Q_Y+even_y[L] < height && q.Q_Y+even_y[L]>=0 ){

										if( !done[q.Q_Y+even_y[L]][q.Q_X+even_x[L]] )QUEUE.push( make_pair(make_pair(q.Q_Y+even_y[L],q.Q_X+even_x[L]),q.Q_depth+1) );

								  	done[q.Q_Y+even_y[L]][q.Q_X+even_x[L]] = true;

							}

						}

					}

				}

				rep(I,100){

					if(dp[I].first){

						if(dp[I].first==1)

							pt[dp[I].second-1]++;

						break;

					}

				}

			}

				answer = max(pt[49],answer);

				point[b_position][a_position] = 0;

			}

			cout << answer << endl;

	}



